/// A UNION TAG AT ITS OWN WIDTH, little-endian, one to eight bytes. The slice
/// is the tag's whole span and never a prefix of it, which is what keeps a
/// foreign 0x0101 from reading as arm 1.
fn table_fixed_tag(b: &[u8]) -> u64 {
    let mut v = 0u64;
    for (i, byte) in b.iter().enumerate().take(8) {
        v |= (*byte as u64) << (8 * i);
    }
    v
}

fn get32(b: &[u8], at: usize) -> u32 {
    match b.get(at..at + 4) {
        Some(w) => u32::from_le_bytes(w.try_into().expect("four bytes")),
        None => 0,
    }
}

fn get64(b: &[u8], at: usize) -> u64 {
    match b.get(at..at + 8) {
        Some(w) => u64::from_le_bytes(w.try_into().expect("eight bytes")),
        None => 0,
    }
}

/// §4'S WIDENING RUNGS, and this form spends no rule of its own on them: a kind
/// that GREW since the writer decodes at the writer's width and lands exactly,
/// counting one widened. Coming back DOWN the ladder, or across two of them, is
/// a kind that MOVED and is reported rather than reinterpreted.
fn widens(from: u8, to: u8) -> bool {
    if (6..=9).contains(&from) && (6..=9).contains(&to) {
        return to > from; // u8 .. u64
    }
    if (2..=5).contains(&from) && (2..=5).contains(&to) {
        return to > from; // i8 .. i64
    }
    // THE FIXED-POINT LADDERS, one rung per storage width and INSIDE a family:
    // 20..24 is a SIGNED fixed(I,F) at 8/16/32/64/128 bits and 25..29 is the
    // unsigned run (§1's kind codes). A grown I at an equal F is a widen; F
    // moving is not a version at all and the lock refuses it.
    if (20..=24).contains(&from) && (20..=24).contains(&to) {
        return to > from;
    }
    if (25..=29).contains(&from) && (25..=29).contains(&to) {
        return to > from;
    }
    from == 10 && to == 11 // f32 -> f64
}

fn signed_kind(kind: u8) -> bool {
    // A LADDER WIDEN'S SIGN IS THE WRITER'S KIND: i8..i64 and a SIGNED
    // fixed-point (20..24) sign-extend, and everything else — the unsigned
    // integers, the unsigned fixed-point run — extends with zero (§5.2).
    (2..=5).contains(&kind) || (20..=24).contains(&kind)
}

// ---- THE ONE READ LOOP ------------------------------------------------------
//
// A READ IS THE HOLES OF THIS PLAN, THIS LOOP, AND NOTHING ELSE. Which plan it
// was handed is the only thing that differs between reading this build's own
// record and reading anybody else's, which is the owner's ruling that this
// form's cost must not move when a peer ships. The prefill copies defaults into
// exactly the dest ranges the plan does not write; identity's list is empty.
//
// EVERY REACH INTO `src` IS CHECKED, because `src` is framed by a stranger's
// block: a plan offset past the record is framing damage, and it is reported
// as such rather than trusted.

/// Runs one plan over one record body, landing it in `image`.
pub fn table_fixed_run(
    plan: &[TableFixedEntry],
    remap: &[u16],
    src: &[u8],
    image: &mut [u8],
    report: &mut TableFixedReport,
) {
    for p in plan {
        if p.guard != TABLE_FIXED_NO_GUARD {
            // THE TAG IS COMPARED AT ITS OWN WIDTH. A two- or four-byte tag
            // whose low byte happens to be 1 is not arm 1: it is an ordinal
            // this build has no arm for, and reading only the first byte let
            // 0x0101 run arm 1's entries over a stranger's record.
            let g = p.guard as usize;
            let w = p.argw as usize;
            match src.get(g..g + w) {
                Some(tag) if table_fixed_tag(tag) == p.arg => {}
                Some(_) => continue,
                None => {
                    report.malformed = true;
                    return;
                }
            }
        }
        let s = p.src as usize;
        let d = p.dst as usize;
        match p.op {
            TableFixedOp::Copy => {
                let n = p.size as usize;
                match (src.get(s..s + n), image.get_mut(d..d + n)) {
                    (Some(from), Some(into)) => into.copy_from_slice(from),
                    _ => {
                        report.malformed = true;
                        return;
                    }
                }
            }
            TableFixedOp::Count => {
                if src.len() < s + 4 || image.len() < d + 4 {
                    report.malformed = true;
                    return;
                }
                let raw = get32(src, s) as i32;
                let held = raw.clamp(0, p.size as i32);
                if held != raw {
                    report.clamped += 1;
                }
                image[d..d + 4].copy_from_slice(&held.to_le_bytes());
            }
            TableFixedOp::Text => {
                let n = p.size as usize;
                if src.len() < s + 4 + n || image.len() < d + 4 + n {
                    report.malformed = true;
                    return;
                }
                let raw = get32(src, s) as i32;
                let held = raw.clamp(0, p.aux as i32);
                if held != raw {
                    report.clamped += 1;
                }
                image[d..d + 4].copy_from_slice(&held.to_le_bytes());
                let (head, tail) = image.split_at_mut(d + 4);
                let _ = &head;
                tail[..n].copy_from_slice(&src[s + 4..s + 4 + n]);
            }
            TableFixedOp::Ordinal => {
                // A VARIANT ORDINAL IS ITS POSITION IN THE BLOCK, so a writer
                // whose enum gained a variant IN THE MIDDLE is remapped here
                // and never reinterpreted.
                let n = p.size as usize;
                let w = p.dstsize as usize;
                if src.len() < s + n || image.len() < d + w {
                    report.malformed = true;
                    return;
                }
                let mut raw: u64 = 0;
                for i in 0..n {
                    raw |= u64::from(src[s + i]) << (8 * i);
                }
                let base = p.aux as usize;
                let held = match remap.get(base) {
                    Some(count) if raw != 0 && raw <= u64::from(*count) => {
                        u64::from(remap[base + raw as usize])
                    }
                    Some(count) => {
                        // AN ORDINAL PAST THE WRITER'S OWN LAST VARIANT IS OUT
                        // OF RANGE, as a count past its bound is: it lands as
                        // None and counts one clamped. A variant the writer DOES
                        // carry and this reader cannot name is a different thing
                        // — it resolves to None through the table and counts
                        // nothing, because nothing was out of range.
                        if raw > u64::from(*count) {
                            report.clamped += 1;
                        }
                        0
                    }
                    None => 0,
                };
                for i in 0..w {
                    image[d + i] = (held >> (8 * i)) as u8;
                }
            }
            TableFixedOp::Widen => {
                let n = p.size as usize;
                let w = p.dstsize as usize;
                if src.len() < s + n || image.len() < d + w || n == 0 || n > 8 {
                    report.malformed = true;
                    return;
                }
                let mut raw: u64 = 0;
                for i in 0..n {
                    raw |= u64::from(src[s + i]) << (8 * i);
                }
                if p.sign != 0 {
                    // TWO'S COMPLEMENT WIDENS BY ITS SIGN BIT, which is the
                    // whole reason a widen is an op and not a short copy.
                    let top = 1u64 << (n * 8 - 1);
                    if raw & top != 0 {
                        raw |= !((top << 1).wrapping_sub(1));
                    }
                }
                for i in 0..w {
                    image[d + i] = (raw >> (8 * i)) as u8;
                }
                report.widened += 1;
            }
            TableFixedOp::WidenF => {
                if src.len() < s + 4 || image.len() < d + 8 {
                    report.malformed = true;
                    return;
                }
                let f = f32::from_le_bytes(src[s..s + 4].try_into().expect("four bytes"));
                image[d..d + 8].copy_from_slice(&f64::from(f).to_le_bytes());
                report.widened += 1;
            }
            TableFixedOp::Const => {
                // NO BYTE LANE, AND NO FOUR-BYTE ONE EITHER (§5.8 row 5): a
                // union tag is one, two, four or EIGHT bytes wide, and the
                // ordinal this op lands is full width on both sides. Refusing
                // a size past four called a lawful eight-byte tag row malformed,
                // and a u32 shifted by 32 would overflow besides — so the
                // value widens before it is taken apart.
                let n = p.size as usize;
                if image.len() < d + n || n > 8 {
                    report.malformed = true;
                    return;
                }
                let v = u64::from(p.aux);
                for i in 0..n {
                    image[d + i] = (v >> (8 * i)) as u8;
                }
            }
        }
    }
}

/// Complement of the unguarded dest writes. Guarded entries (union arms,
/// compiled tag consts) are not always written, so they stay holes and keep
/// the defaults. The write sizes match table_fixed_run. cover is scratch the
/// size of the destination image; out holds at most cover.len() holes.
pub fn table_fixed_holes(
    plan: &[TableFixedEntry],
    cover: &mut [u8],
    out: &mut [TableFixedHole],
) -> usize {
    cover.fill(0);
    for p in plan {
        if p.guard != TABLE_FIXED_NO_GUARD {
            continue;
        }
        let (off, n) = match p.op {
            TableFixedOp::Copy | TableFixedOp::Const => (p.dst, p.size),
            TableFixedOp::Count => (p.dst, 4),
            TableFixedOp::Text => (p.dst, 4u32.saturating_add(p.size)),
            TableFixedOp::Ordinal | TableFixedOp::Widen => (p.dst, u32::from(p.dstsize)),
            TableFixedOp::WidenF => (p.dst, 8),
        };
        if n == 0 {
            continue;
        }
        let start = off as usize;
        if start >= cover.len() {
            continue;
        }
        let end = start.saturating_add(n as usize).min(cover.len());
        cover[start..end].fill(1);
    }
    let mut n = 0usize;
    let mut i = 0usize;
    while i < cover.len() {
        if cover[i] != 0 {
            i += 1;
            continue;
        }
        let start = i;
        i += 1;
        while i < cover.len() && cover[i] == 0 {
            i += 1;
        }
        if n < out.len() {
            out[n] = TableFixedHole {
                off: start as u32,
                size: (i - start) as u32,
            };
            n += 1;
        }
    }
    n
}

// ---- THE BLOCK --------------------------------------------------------------
//
// An entry is SEVENTEEN BYTES and the block is a count and a run of them. THE
// FORMAT NEVER MOVES, which is what lets a reader of this major parse a later
// major's block and step over a kind it does not know by the size the entry
// states.

const ENTRY_BYTES: usize = 17;
const MAX_DEPTH: u32 = 64;

fn ordinal_width(n: u32) -> bool {
    n == 1 || n == 2 || n == 4 || n == 8
}

fn known_kind(kind: u8) -> bool {
    (1..=30).contains(&kind) || kind == 32 || kind == 33 || kind == 35
}

fn leaf_size(kind: u8, size: u32) -> Option<bool> {
    let ok = match kind {
        1 => size == 1,
        2 => size == 1,
        3 => size == 2,
        4 => size == 4,
        5 => size == 8,
        6 => size == 1 || size == 4,
        7 => size == 2 || size == 4,
        8 => size == 4,
        9 => size == 8,
        10 => size == 4,
        11 => size == 8,
        17 => size == 4,
        18 | 19 => size == 16,
        20 | 25 => size == 1,
        21 | 26 => size == 2,
        22 | 27 => size == 4,
        23 | 28 => size == 8,
        24 | 29 => size == 16,
        32 => size == 0,
        _ => return None,
    };
    Some(ok)
}

/// One block entry, read out of the bytes.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct TableFixedBlockEntry {
    pub id: u64,
    pub size: u32,
    pub children: u32,
    pub kind: u8,
}

/// A parsed block: the bytes and the entry count, and nothing else. Parsing is
/// a bounds check and a proof that the TREE CLOSES, which is what lets every
/// walk below index without re-checking.
#[derive(Clone, Copy)]
pub struct TableFixedBlock<'a> {
    bytes: &'a [u8],
    count: usize,
}

impl<'a> TableFixedBlock<'a> {
    pub fn parse(bytes: &'a [u8]) -> Result<TableFixedBlock<'a>, TableFixedReason> {
        if bytes.len() < 4 {
            return Err(TableFixedReason::LayoutMalformed);
        }
        let count = get32(bytes, 0) as usize;
        let entry_bytes_len = match count.checked_mul(ENTRY_BYTES).and_then(|b| b.checked_add(4)) {
            Some(len) => len,
            None => return Err(TableFixedReason::LayoutCountMismatch),
        };
        if count == 0 || entry_bytes_len != bytes.len() {
            return Err(TableFixedReason::LayoutCountMismatch);
        }
        let block = TableFixedBlock { bytes, count };
        let root = block.entry(0);
        if root.kind != 13 {
            return Err(TableFixedReason::LayoutKindInvalid);
        }
        if root.size == 0 || root.size > 65536 {
            return Err(TableFixedReason::LayoutRecordTooLarge);
        }
        let used = block.check_entry(0, 0)?;
        if used != count {
            return Err(TableFixedReason::LayoutTreeUnclosed);
        }
        Ok(block)
    }

    pub fn count(&self) -> usize {
        self.count
    }

    pub fn entry(&self, i: usize) -> TableFixedBlockEntry {
        if i >= self.count {
            return TableFixedBlockEntry::default();
        }
        let e = 4 + i * ENTRY_BYTES;
        TableFixedBlockEntry {
            id: get64(self.bytes, e),
            kind: self.bytes[e + 8],
            size: get32(self.bytes, e + 9),
            children: get32(self.bytes, e + 13),
        }
    }

    /// How many entries the subtree rooted at `i` occupies, so a walk steps over
    /// a child it does not want without knowing what is in it.
    pub fn subtree(&self, i: usize) -> usize {
        self.subtree_at(i, 0).unwrap_or(1)
    }

    fn subtree_at(&self, i: usize, depth: u32) -> Option<usize> {
        if depth > MAX_DEPTH || i >= self.count {
            return None;
        }
        let e = self.entry(i);
        let mut n = 1usize;
        let mut at = i + 1;
        for _ in 0..e.children {
            if at >= self.count {
                return None;
            }
            let sub = self.subtree_at(at, depth + 1)?;
            at += sub;
            n += sub;
        }
        Some(n)
    }

    fn check_entry(&self, i: usize, depth: u32) -> Result<usize, TableFixedReason> {
        if i >= self.count {
            return Err(TableFixedReason::LayoutTreeUnclosed);
        }
        if depth > MAX_DEPTH {
            return Err(TableFixedReason::LayoutTooDeep);
        }
        let e = self.entry(i);
        if !known_kind(e.kind) {
            return Err(TableFixedReason::LayoutKindUnknown);
        }
        if e.size > 65536 {
            return Err(TableFixedReason::LayoutRecordTooLarge);
        }

        let mut at = i + 1;
        let mut sum = 0u64;
        let mut widest = 0u32;
        let mut first_size = 0u32;
        let mut second_size = 0u32;
        let mut first_kind = 0u8;
        let mut first_children = 0u32;
        let mut kids_are_variants = true;

        for k in 0..e.children {
            let child = at;
            let used = self.check_entry(child, depth + 1)?;
            let ce = self.entry(child);
            if k == 0 {
                first_size = ce.size;
                first_kind = ce.kind;
                first_children = ce.children;
            }
            if k == 1 {
                second_size = ce.size;
            }
            if ce.kind != 32 {
                kids_are_variants = false;
            }
            sum = sum.saturating_add(ce.size as u64);
            if ce.size > widest {
                widest = ce.size;
            }
            if sum > 65536 {
                return Err(TableFixedReason::LayoutRecordTooLarge);
            }
            at += used;
        }

        if let Some(ok) = leaf_size(e.kind, e.size) {
            if !ok {
                return Err(TableFixedReason::LayoutSizeMismatch);
            }
            if e.children != 0 {
                return Err(TableFixedReason::LayoutKindInvalid);
            }
            return Ok(at - i);
        }

        match e.kind {
            13 => {
                if e.size as u64 != sum {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
            }
            35 => {
                if e.children != 1 {
                    return Err(TableFixedReason::LayoutKindInvalid);
                }
                if e.size as u64 != sum + 1 {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
            }
            14 => {
                if e.children != 1 {
                    return Err(TableFixedReason::LayoutKindInvalid);
                }
                if first_size == 0 {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
                let bare = (e.size % first_size) == 0;
                let counted = e.size >= 4 && ((e.size - 4) % first_size) == 0;
                if !bare && !counted {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
            }
            16 => {
                if e.children != 2 || first_kind != 30 {
                    return Err(TableFixedReason::LayoutKindInvalid);
                }
                if second_size == 0 || (e.size % second_size) != 0 {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
                if (e.size / second_size) < first_children {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
            }
            15 => {
                if e.children == 0 {
                    return Err(TableFixedReason::LayoutKindInvalid);
                }
                if e.size <= widest || !ordinal_width(e.size - widest) {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
            }
            30 => {
                if !ordinal_width(e.size) {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
                if e.children != 0 && !kids_are_variants {
                    return Err(TableFixedReason::LayoutKindInvalid);
                }
            }
            12 => {
                if e.children != 0 {
                    return Err(TableFixedReason::LayoutKindInvalid);
                }
                if e.size < 4 {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
            }
            33 => {
                if e.children != 0 {
                    return Err(TableFixedReason::LayoutKindInvalid);
                }
                if e.size < 4 || ((e.size - 4) % 2) != 0 {
                    return Err(TableFixedReason::LayoutSizeMismatch);
                }
            }
            _ => {
                return Err(TableFixedReason::LayoutKindUnknown);
            }
        }
        Ok(at - i)
    }

    /// A union's tag width: what its entry's size has left over the widest arm.
    fn tag_bytes(&self, i: usize) -> u32 {
        self.entry(i).size.saturating_sub(self.widest_arm(i))
    }

    fn widest_arm(&self, i: usize) -> u32 {
        let e = self.entry(i);
        let mut widest = 0;
        let mut at = i + 1;
        for _ in 0..e.children {
            if at >= self.count {
                break;
            }
            let a = self.entry(at);
            if a.size > widest {
                widest = a.size;
            }
            at += self.subtree(at);
        }
        widest
    }
}

// ---- THE PLAN COMPILER ------------------------------------------------------
//
// The SAME LOOP runs over this plan as over the identity plan. What the
// compiler does, ONCE PER PEER, is what a read would otherwise do once per
// record: map the writer's ids onto this reader's fields; leave a field it
// cannot name OUT of the plan, which is what skips it, by arithmetic that was
// going to step past it anyway; and leave a field the writer does not carry out
// too, which is what defaults it, because the prefill already put the declared
// default there.
//
// MY DESTINATION OFFSET IS MY DECLARED OFFSET. That is the whole of what this
// port saves by planning in the image domain: C++ carries a side table of
// storage offsets, strides and text buffers beside its block, and here the same
// walk that produced my block produces my offsets.

struct Compiler<'a> {
    plan: &'a mut [TableFixedEntry],
    remap: &'a mut [u16],
    count: usize,
    remap_used: usize,
    overflow: bool,
}

impl Compiler<'_> {
    fn push(&mut self, e: TableFixedEntry) {
        if self.count >= self.plan.len() {
            self.overflow = true;
            return;
        }
        self.plan[self.count] = e;
        self.count += 1;
    }

    /// Lays a remap table down and answers where it starts: a count, then that
    /// many landed ordinals.
    /// RESERVE a remap table of `n` entries and write its LENGTH WORD, returning
    /// the table's byte offset from the pool's base. The table is filled in
    /// place afterwards, so its length is the WRITER's variant count and not a
    /// temporary's capacity (§5.2): a cap would remap a writer's variant past
    /// the cap to None as though this reader did not name it, which is a silent
    /// wrong value and not a refusal. A count past what the length word can
    /// hold is the pool's own overflow, plan_too_large by name.
    fn reserve(&mut self, n: usize) -> Option<u32> {
        let at = self.remap_used;
        if n > u16::MAX as usize || at + 1 + n > self.remap.len() {
            self.overflow = true;
            return None;
        }
        self.remap[at] = n as u16;
        self.remap[at + 1..at + 1 + n].fill(0);
        self.remap_used = at + 1 + n;
        Some(at as u32)
    }

    /// Entry `j` of the table at `at`: the reader's position of the writer's
    /// variant `j`, or 0 where this reader has no such name.
    fn place(&mut self, at: u32, j: usize, landed: u16) {
        let i = at as usize + 1 + j;
        if i < self.remap.len() {
            self.remap[i] = landed;
        }
    }

}

/// Compiles a plan that reads `theirs`-shaped records into `mine`-shaped images.
///
/// `counted` is MY side of MY block, one byte an entry, saying whether an array
/// entry carries a live count in front of it — the one storage fact a block
/// entry cannot state. Returns the entries written, or None when the caller's
/// plan or remap storage does not hold it.
pub fn table_fixed_compile(
    theirs: &TableFixedBlock,
    mine: &TableFixedBlock,
    counted: &[u8],
    plan: &mut [TableFixedEntry],
    remap: &mut [u16],
    report: &mut TableFixedReport,
) -> Option<usize> {
    let mut c = Compiler {
        plan,
        remap,
        count: 0,
        remap_used: 0,
        overflow: false,
    };
    match_children(&mut c, theirs, 0, 0, mine, 0, 0, counted, TABLE_FIXED_NO_GUARD, 0, 1, 0, report);
    if c.overflow {
        return None;
    }
    // COALESCE, which is the only optimization a plan compiler performs and is
    // performed identically on both sides: two neighbouring copies whose source
    // and destination both advance together are one entry.
    let count = c.count;
    let mut out = 0usize;
    for i in 0..count {
        if out > 0
            && c.plan[out - 1].op == TableFixedOp::Copy
            && c.plan[i].op == TableFixedOp::Copy
            && c.plan[out - 1].guard == c.plan[i].guard
            && c.plan[out - 1].arg == c.plan[i].arg
            && c.plan[out - 1].argw == c.plan[i].argw
            && c.plan[out - 1].src + c.plan[out - 1].size == c.plan[i].src
            && c.plan[out - 1].dst + c.plan[out - 1].size == c.plan[i].dst
        {
            c.plan[out - 1].size += c.plan[i].size;
            continue;
        }
        c.plan[out] = c.plan[i];
        out += 1;
    }
    Some(out)
}

/// Walks a TABLE's children on both sides, matching by id.
fn match_children(
    c: &mut Compiler,
    theirs: &TableFixedBlock,
    ti: usize,
    their_at: u32,
    mine: &TableFixedBlock,
    mi: usize,
    my_at: u32,
    counted: &[u8],
    guard: u32,
    arg: u64,
    argw: u8,
    depth: u32,
    report: &mut TableFixedReport,
) {
    if depth > MAX_DEPTH {
        c.overflow = true;
        return;
    }
    let te = theirs.entry(ti);
    let me = mine.entry(mi);
    let mut my_child = mi + 1;
    let mut my_off = my_at;
    for _ in 0..me.children {
        let mc = mine.entry(my_child);
        let mut their_child = ti + 1;
        let mut their_off = their_at;
        for _ in 0..te.children {
            let tc = theirs.entry(their_child);
            if tc.id == mc.id {
                compile_entry(
                    c, theirs, their_child, their_off, mine, my_child, my_off, counted, guard, arg, argw,
                    depth + 1, report,
                );
                break;
            }
            their_off = their_off.saturating_add(tc.size);
            their_child += theirs.subtree(their_child);
        }
        my_off = my_off.saturating_add(mc.size);
        my_child += mine.subtree(my_child);
    }
    // EVERY FIELD OF THEIRS I COULD NOT NAME IS ONE unknown, and skipping it
    // costs nothing because skipping is not an act: the next entry's src is
    // already past it.
    let mut tc_at = ti + 1;
    for _ in 0..te.children {
        let tc = theirs.entry(tc_at);
        let mut named = false;
        let mut mc_at = mi + 1;
        for _ in 0..me.children {
            if mine.entry(mc_at).id == tc.id {
                named = true;
                break;
            }
            mc_at += mine.subtree(mc_at);
        }
        if !named {
            report.unknown += 1;
        }
        tc_at += theirs.subtree(tc_at);
    }
}

fn compile_entry(
    c: &mut Compiler,
    theirs: &TableFixedBlock,
    ti: usize,
    their_at: u32,
    mine: &TableFixedBlock,
    mi: usize,
    my_at: u32,
    counted: &[u8],
    guard: u32,
    arg: u64,
    argw: u8,
    depth: u32,
    report: &mut TableFixedReport,
) {
    if depth > MAX_DEPTH {
        c.overflow = true;
        return;
    }
    let te = theirs.entry(ti);
    let me = mine.entry(mi);
    // T INTO ?T (§5.2's EMIT, bill §12.8): this reader WRAPPED a value the
    // writer sent bare. The present byte is not on the wire at all, so it is a
    // CONSTANT 1 this reader's own image takes — carried under the same guard
    // and ordinal as the payload, so a present byte under an arm the tag did
    // not name is not set — and then the payload lands against the wrapper's
    // own child. (§5.2's EMIT says "under guard/arg" where §5.7's C-leg row
    // calls the same constant UNGUARDED; the guarded reading is the one that
    // cannot set a present byte for an arm nobody selected. AT TOP LEVEL THE
    // TWO READINGS COINCIDE: the guard a root field inherits is the empty one,
    // which is the unguarded case the bill names, so the readings part only
    // under a union arm — where the guarded one is right.)
    if me.kind == 35 && te.kind != 35 {
        c.push(TableFixedEntry {
            src: their_at,
            dst: my_at,
            size: 1,
            aux: 1,
            guard,
            arg,
            argw,
            op: TableFixedOp::Const,
            ..TableFixedEntry::default()
        });
        compile_entry(
            c, theirs, ti, their_at, mine, mi + 1, my_at + 1, counted, guard, arg, argw, depth + 1,
            report,
        );
        return;
    }
    if te.kind != me.kind {
        if widens(te.kind, me.kind) {
            c.push(TableFixedEntry {
                src: their_at,
                dst: my_at,
                size: te.size,
                dstsize: me.size as u8,
                guard,
                arg,
                argw,
                op: if te.kind == 10 {
                    TableFixedOp::WidenF
                } else {
                    TableFixedOp::Widen
                },
                sign: u8::from(signed_kind(te.kind)),
                ..TableFixedEntry::default()
            });
            return;
        }
        // A KIND THAT MOVED IS REPORTED AND NEVER REINTERPRETED (§4).
        report.kind_mismatch += 1;
        return;
    }
    match me.kind {
        35 => {
            // the OPTIONAL wrapper: the present byte, then the payload whole
            c.push(TableFixedEntry {
                src: their_at,
                dst: my_at,
                size: 1,
                guard,
                arg,
                argw,
                op: TableFixedOp::Copy,
                ..TableFixedEntry::default()
            });
            compile_entry(
                c, theirs, ti + 1, their_at + 1, mine, mi + 1, my_at + 1, counted, guard, arg, argw,
                depth + 1, report,
            );
        }
        13 => match_children(
            c, theirs, ti, their_at, mine, mi, my_at, counted, guard, arg, argw, depth + 1, report,
        ),
        14 => {
            // an array: the count, then min( their bound, my bound ) elements
            let tel = theirs.entry(ti + 1);
            let mel = mine.entry(mi + 1);
            let head = if counted.get(mi).copied().unwrap_or(0) != 0 {
                4u32
            } else {
                0u32
            };
            let their_n = te.size.saturating_sub(head).checked_div(tel.size).unwrap_or(0);
            let my_n = me.size.saturating_sub(head).checked_div(mel.size).unwrap_or(0);
            if head != 0 {
                // THE COUNT'S BOUND IS THE WRITER'S, carried by the plan (bill
                // §12.5, §5.2's EMIT at kind 14): a count forged past what THAT
                // PEER could have written clamps and counts, and a count the
                // reader merely grew room for does not. The min is not the
                // rule — it is the floor under a lock that is not monotone,
                // which is a build bug and never a wire event.
                c.push(TableFixedEntry {
                    src: their_at,
                    dst: my_at,
                    size: their_n.min(my_n),
                    guard,
                    arg,
                    argw,
                    op: TableFixedOp::Count,
                    ..TableFixedEntry::default()
                });
            }
            let n = their_n.min(my_n);
            for i in 0..n {
                compile_entry(
                    c,
                    theirs,
                    ti + 1,
                    their_at + head + i * tel.size,
                    mine,
                    mi + 1,
                    my_at + head + i * mel.size,
                    counted,
                    guard,
                    arg,
                    argw,
                    depth + 1,
                    report,
                );
            }
        }
        16 => {
            // an enum-keyed array: every slot, matched by the KEY's id, because
            // a key that slid is a slot that moved and never a slot that means
            // something else
            let tkey = theirs.entry(ti + 1);
            let mkey = mine.entry(mi + 1);
            let tel = ti + 1 + theirs.subtree(ti + 1);
            let mel = mi + 1 + mine.subtree(mi + 1);
            let tee = theirs.entry(tel);
            let mee = mine.entry(mel);
            for k in 0..mkey.children as usize {
                let key_id = mine.entry(mi + 2 + k).id;
                for j in 0..tkey.children as usize {
                    if theirs.entry(ti + 2 + j).id != key_id {
                        continue;
                    }
                    compile_entry(
                        c,
                        theirs,
                        tel,
                        their_at + j as u32 * tee.size,
                        mine,
                        mel,
                        my_at + k as u32 * mee.size,
                        counted,
                        guard,
                        arg,
                        argw,
                        depth + 1,
                        report,
                    );
                    break;
                }
            }
        }
        15 => {
            // a union: MY tag written under THEIR tag's guard, then each arm
            // matched by id. Nothing in this port declares one yet (the Row
            // follow-on), and a stranger's union still lands correctly here.
            let their_tag = theirs.tag_bytes(ti);
            let my_tag = mine.tag_bytes(mi);
            let mut my_arm = mi + 1;
            for k in 0..me.children as usize {
                let ma = mine.entry(my_arm);
                let mut their_arm = ti + 1;
                for j in 0..te.children as usize {
                    let ta = theirs.entry(their_arm);
                    if ta.id == ma.id {
                        c.push(TableFixedEntry {
                            src: their_at,
                            dst: my_at,
                            size: my_tag,
                            aux: k as u32 + 1,
                            guard: their_at,
                            arg: j as u64 + 1,
                            argw: their_tag as u8,
                            op: TableFixedOp::Const,
                            ..TableFixedEntry::default()
                        });
                        compile_entry(
                            c,
                            theirs,
                            their_arm,
                            their_at + their_tag,
                            mine,
                            my_arm,
                            my_at + my_tag,
                            counted,
                            their_at,
                            j as u64 + 1,
                            their_tag as u8,
                            depth + 1,
                            report,
                        );
                        break;
                    }
                    their_arm += theirs.subtree(their_arm);
                }
                my_arm += mine.subtree(my_arm);
            }
        }
        30 if te.size < me.size => {
            // A GROWN ORDINAL WIDTH IS A WIDEN, and it is UNSIGNED (§5.2's EMIT
            // at kind 30, bill §12.7): the writer's variant NAMES did not move,
            // only the width the ordinal rides at, so there is nothing to remap
            // and the counter this moves is widened (§5.4) and not clamped.
            // The same-kind widen extends with ZERO — the entry's sign is left
            // at zero and never inferred from the kind's signedness.
            c.push(TableFixedEntry {
                src: their_at,
                dst: my_at,
                size: te.size,
                guard,
                arg,
                argw,
                op: TableFixedOp::Widen,
                dstsize: me.size as u8,
                ..TableFixedEntry::default()
            });
        }
        30 => {
            // an enum: the ordinal is the block's POSITION, so it remaps by
            // NAME and a variant inserted in the middle never reinterprets one.
            //
            // THE TABLE IS AS LONG AS THE WRITER'S VARIANT COUNT (§5.2), which
            // is why it is reserved in the pool and filled in place rather than
            // built in a fixed temporary: a table capped at 255 remaps a
            // writer's 256th variant and every one after it to None as though
            // this reader did not name them, and a wrong value nobody is told
            // about is worse than a refusal. The length word is slot 0, so an
            // ordinal of 0 is None BY CONSTRUCTION and never an index.
            let n = te.children as usize;
            let Some(aux) = c.reserve(n) else {
                return; // the pool is spent: the plan does not fit, by name
            };
            for j in 0..n {
                let vid = theirs.entry(ti + 1 + j).id;
                let mut landed = 0u16;
                for k in 0..me.children as usize {
                    if mine.entry(mi + 1 + k).id == vid {
                        landed = (k + 1) as u16;
                        break;
                    }
                }
                c.place(aux, j, landed);
            }
            c.push(TableFixedEntry {
                src: their_at,
                dst: my_at,
                size: te.size,
                aux,
                guard,
                arg,
                argw,
                op: TableFixedOp::Ordinal,
                dstsize: me.size as u8,
                ..TableFixedEntry::default()
            });
        }
        12 | 33 => {
            // text: the length, clamped to MY bound in units, then the content
            let unit = if me.kind == 33 { 2u32 } else { 1u32 };
            let bytes = me.size.saturating_sub(4).min(te.size.saturating_sub(4));
            // THE CAP IS THE SPAN'S, IN UNITS, AND THE SPAN IS THE SHORTER OF
            // THE TWO (§5.2 TEXT: span := min(me.size, te.size) - 4, cap :=
            // span / unit). The READER's own bound is the wrong number here: a
            // reader whose bound GREW copies only the writer's span, so a
            // length between the writer's bound and the reader's reads bytes
            // this entry never landed, and the clamp that should have fired and
            // counted does not.
            c.push(TableFixedEntry {
                src: their_at,
                dst: my_at,
                size: bytes,
                aux: bytes.checked_div(unit).unwrap_or(0),
                guard,
                arg,
                argw,
                op: TableFixedOp::Text,
                ..TableFixedEntry::default()
            });
        }
        _ => {
            if te.size == me.size {
                c.push(TableFixedEntry {
                    src: their_at,
                    dst: my_at,
                    size: me.size,
                    guard,
                    arg,
                    argw,
                    op: TableFixedOp::Copy,
                    ..TableFixedEntry::default()
                });
            } else if te.size < me.size && me.size <= 8 {
                c.push(TableFixedEntry {
                    src: their_at,
                    dst: my_at,
                    size: te.size,
                    dstsize: me.size as u8,
                    guard,
                    arg,
                    argw,
                    op: TableFixedOp::Widen,
                    // A SAME-KIND WIDEN ZERO-EXTENDS (§5.2: ladder widen, sign
                    // by the WRITER's kind; same-kind widen and enum widen,
                    // ZERO). Inferring the sign from the kind agrees by
                    // accident today — the only same-kind rows admitting two
                    // widths are 6 and 7 at a bits(N) storage width and kind
                    // 30, all unsigned — and it is a DIFFERENT RULE that
                    // diverges the first day a signed kind admits two widths.
                    sign: 0,
                    ..TableFixedEntry::default()
                });
            } else {
                report.kind_mismatch += 1;
            }
        }
    }
}
